class Solution:
    def minimumTimeRequired(self, jobs: List[int], k: int) -> int:
        jobs.sort(reverse=True)
        n = len(jobs)
        loads = [0] * k
        best = sum(jobs)

        def dfs(i: int, cur: int) -> None:
            nonlocal best
            if cur >= best:
                return
            if i == n:
                best = cur
                return
            for w in range(k):
                if any(loads[t] == loads[w] for t in range(w)):
                    continue
                loads[w] += jobs[i]
                dfs(i + 1, max(cur, loads[w]))
                loads[w] -= jobs[i]

        dfs(0, 0)
        return best

