class Solution {
    int best;
    vector<int> loads_;

    void dfs(vector<int>& jobs, int i, int cur, int k) {
        if (cur >= best) return;
        if (i == (int)jobs.size()) { best = cur; return; }
        for (int w = 0; w < k; ++w) {
            bool dup = false;
            for (int t = 0; t < w; ++t)
                if (loads_[t] == loads_[w]) { dup = true; break; }
            if (dup) continue;
            loads_[w] += jobs[i];
            dfs(jobs, i + 1, max(cur, loads_[w]), k);
            loads_[w] -= jobs[i];
        }
    }

public:
    int minimumTimeRequired(vector<int>& jobs, int k) {
        sort(jobs.rbegin(), jobs.rend());
        best = accumulate(jobs.begin(), jobs.end(), 0);
        loads_.assign(k, 0);
        dfs(jobs, 0, 0, k);
        return best;
    }
};

