class Solution {
    private int best;
    private int[] loads;

    public int minimumTimeRequired(int[] jobs, int k) {
        Arrays.sort(jobs);
        for (int l = 0, r = jobs.length - 1; l < r; l++, r--) {
            int t = jobs[l]; jobs[l] = jobs[r]; jobs[r] = t;
        }
        int sum = 0;
        for (int j : jobs) sum += j;
        best = sum;
        loads = new int[k];
        dfs(jobs, 0, 0, k);
        return best;
    }

    private void dfs(int[] jobs, int i, int cur, int k) {
        if (cur >= best) return;
        if (i == jobs.length) { best = cur; return; }
        for (int w = 0; w < k; w++) {
            boolean dup = false;
            for (int t = 0; t < w; t++)
                if (loads[t] == loads[w]) { dup = true; break; }
            if (dup) continue;
            loads[w] += jobs[i];
            dfs(jobs, i + 1, Math.max(cur, loads[w]), k);
            loads[w] -= jobs[i];
        }
    }
}

