class Solution:
    def minimumTimeRequired(self, jobs: List[int], k: int) -> int:
        n = len(jobs)
        size = 1 << n
        sums = [0] * size
        for mask in range(1, size):
            low = mask & -mask
            sums[mask] = sums[mask ^ low] + jobs[low.bit_length() - 1]
        INF = float("inf")
        dp = sums[:]  # one worker
        for _ in range(k - 1):
            ndp = dp[:]
            for mask in range(1, size):
                sub = mask
                while sub:
                    cand = max(dp[mask ^ sub], sums[sub])
                    if cand < ndp[mask]:
                        ndp[mask] = cand
                    sub = (sub - 1) & mask
            dp = ndp
        return dp[size - 1]

