class Solution {
public:
    int minimumTimeRequired(vector<int>& jobs, int k) {
        int n = jobs.size(), size = 1 << n, full = size - 1;
        vector<int> sums(size, 0);
        for (int mask = 1; mask < size; ++mask) {
            int low = mask & (-mask);
            sums[mask] = sums[mask ^ low] + jobs[__builtin_ctz(low)];
        }
        vector<int> dp(sums);  // one worker
        for (int w = 2; w <= k; ++w) {
            vector<int> ndp(dp);
            for (int mask = 1; mask < size; ++mask)
                for (int sub = mask; sub; sub = (sub - 1) & mask)
                    ndp[mask] = min(ndp[mask], max(dp[mask ^ sub], sums[sub]));
            dp = move(ndp);
        }
        return dp[full];
    }
};

