class Solution {
    public int minimumTimeRequired(int[] jobs, int k) {
        int n = jobs.length, size = 1 << n;
        int[] sums = new int[size];
        for (int mask = 1; mask < size; mask++)
            sums[mask] = sums[mask & (mask - 1)] + jobs[Integer.numberOfTrailingZeros(mask)];
        int[] dp = sums.clone();  // one worker
        for (int w = 2; w <= k; w++) {
            int[] ndp = dp.clone();
            for (int mask = 1; mask < size; mask++)
                for (int sub = mask; sub > 0; sub = (sub - 1) & mask)
                    ndp[mask] = Math.min(ndp[mask], Math.max(dp[mask ^ sub], sums[sub]));
            dp = ndp;
        }
        return dp[size - 1];
    }
}

